fn truncate(value: &str, limit: usize) -> String {
    let text = squash(value);
    if text.chars().count() > limit {
        let cut: String = text.chars().take(limit.saturating_sub(1)).collect();
        format!("{cut}…")
    } else {
        text
    }
}

